sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   if (newValue == 'servicio'){
	g_form.setVisible('proveedor_sugerido' , false);
	g_form.setVisible('precio_unitario_estimado' , false);
	g_form.setVisible('monto_total_estimado' , false);

	g_form.clearValue('proveedor_sugerido');
	g_form.clearValue('precio_unitario_estimado');
	g_form.clearValue('monto_total_estimado');
   }else{
	g_form.setVisible('proveedor_sugerido' , true);
	g_form.setVisible('precio_unitario_estimado' , true);
	g_form.setVisible('monto_total_estimado' , true);
   }

}
